&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience selling into enterprise accounts across Northern Europe, such as the UK, Ireland, Nordics, or Benelux.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
